"""Phase 10: the trust report is generated by a command, never by hand (FR-EVL-003, EVALUATION section 6)."""

from __future__ import annotations

import json
import subprocess
import sys
from pathlib import Path

import pytest

ROOT = Path(__file__).resolve().parents[2]
SECTIONS = ["header", "eval_counts", "extraction", "flags", "ai_contribution", "safety", "voice", "integrity", "performance", "worst_cases"]


@pytest.fixture(scope="module")
def report(tmp_path_factory):
    out = tmp_path_factory.mktemp("reports")
    proc = subprocess.run(
        [sys.executable, str(ROOT / "scripts" / "trust_report.py"), "--mode", "rules", "--out", str(out)],
        cwd=ROOT,
        capture_output=True,
        text=True,
        timeout=600,
    )
    assert proc.returncode == 0, proc.stdout[-3000:] + proc.stderr[-3000:]
    js = list(out.glob("*.json"))
    md = list(out.glob("*.md"))
    assert len(js) == 1 and len(md) == 1
    return json.loads(js[0].read_text(encoding="utf-8")), md[0].read_text(encoding="utf-8")


def test_sections_present(report):
    data, md = report
    for s in SECTIONS:
        assert s in data, s
    assert md.startswith("VeriDoc trust report")


def test_header_records_provenance(report):
    h = report[0]["header"]
    assert set(h) >= {"date", "git_commit", "tier", "model", "speech_model", "playbook_versions", "dataset_version", "mode"}
    assert h["mode"] == "rules"
    assert h["model"] is None, "rules-only run names no model"


def test_metrics_are_valid_fractions(report):
    ex = report[0]["extraction"]
    for scope in [ex["overall"], *ex["per_key"].values(), *ex["per_slice"].values()]:
        for m in ("precision", "recall", "f1"):
            assert 0.0 <= scope[m] <= 1.0


def test_safety_targets(report):
    safety = report[0]["safety"]
    assert safety["ungrounded_terms_in_record"] == 0  # NFR-ACC-002
    assert safety["injection_fixtures_changed"] == 0


def test_integrity_section(report):
    integ = report[0]["integrity"]
    assert integ["vectors_python"] == "pass" and integ["tamper_cases_passed"] == 7


def test_voice_section_says_deferred(report):
    assert report[0]["voice"]["status"] == "deferred (PHASES.md R-01)"


def test_report_contains_no_chat_text(report):
    data, md = report
    blob = json.dumps(data, ensure_ascii=False) + md
    from packages.ingest.whatsapp import parse_export

    for chat in (ROOT / "eval" / "chats").glob("*.txt"):
        for m in parse_export(chat.read_bytes()).messages:
            if len(m.text) >= 12:
                assert m.text not in blob, f"report leaks text of {chat.name}"


def test_worst_cases_are_ids_only(report):
    worst = report[0]["worst_cases"]
    assert len(worst) <= 10
    for w in worst:
        assert set(w) <= {"chat_id", "term_key", "reason"}


def test_numbers_are_targets_until_measured(report):
    md = report[1]
    assert "target" in md.lower()
